const body = $input.item.json.body;
const cadena = body.cadena_oficios;
const nombre_biblioteca = body.biblioteca_nombre;
const mision_sistema = body.mision_sistema || "Análisis de documentos.";
const notas_insumos = body.comentarios_adicionales || [];

// 1. Definición de Misión e Instrucciones Base
let texto_para_ia = `MISION CRÍTICA: ${mision_sistema}\n\n`;
texto_para_ia += `Instrucciones: Eres un experto en análisis de documentos y procesos. Analiza los siguientes ${cadena.length} documentos de la biblioteca "${nombre_biblioteca}". Haz énfasis en la trazabilidad: qué documento responde a cuál y si el flujo está completado.\n\n`;

// 2. Integración de Notas e Insumos del Usuario (Si existen)
if (notas_insumos.length > 0) {
    texto_para_ia += `======= NOTAS E INSUMOS DEL USUARIO (Prioridad de Contexto) =======\n`;
    notas_insumos.forEach((nota, idx) => {
        texto_para_ia += `Nota ${idx + 1}: ${nota.titulo}\nContenido: ${nota.contenido}\n\n`;
    });
}

texto_para_ia += `Tu tarea es devolver un resumen ejecutivo en Markdown que proteja los intereses del IOP:\n1. **Contexto**\n2. **Trazabilidad y Flujos** (Quién respondió a quién)\n3. **Análisis de Riesgos/Oportunidades para el IOP**\n4. **Pendientes Críticos**\n\n`;

texto_para_ia += `======= DOCUMENTOS =======\n\n`;

// 3. Procesamiento de Documentos y su Trazabilidad
for(let i=0; i<cadena.length; i++) {
    const doc = cadena[i];
    texto_para_ia += `--- DOCUMENTO: ${doc.codigo} ---\n`;
    texto_para_ia += `Título: ${doc.titulo}\n`;
    texto_para_ia += `Estado: ${doc.estado}\n`;

    if (doc.trazabilidad_hijos && doc.trazabilidad_hijos.length > 0) {
        texto_para_ia += `Trazabilidad (Respuestas a este doc):\n`;
        doc.trazabilidad_hijos.forEach(hijo => {
            texto_para_ia += `  -> Respondido con: ${hijo.codigo} (${hijo.estado})\n`;
        });
    } else {
        texto_para_ia += `Trazabilidad: Este documento no tiene respuestas registradas aún.\n`;
    }

    texto_para_ia += `Texto Extraído:\n${doc.texto_extraido || 'Sin texto disponible.'}\n\n`;
}

return { texto_redactado: texto_para_ia };

